                    System.out.printf(Locale.US, "TOTAL_ENEMIES=%d%n", totalEnemies);
                    float progress = levelPaths.isEmpty() ? 0.0f : manager.getProgress();
                    System.out.printf(Locale.US, "PROGRESS=%.2f%n", progress);
                    System.out.println("DONE");
                    System.out.flush();
                    manager.dispose();
                    manager = null;
                    Gdx.app.exit();
                }
            }
        }

        @Override
        public void dispose() {
            if (manager != null) {
                manager.dispose();
            }
        }
    }
}

